SELECT id, tuid, uid, session_id, tid, parent_tid, user_json, ai_json, created_at, last_accessed_at
FROM turns
WHERE session_id = #{sessionId,typeHandler=org.apache.ibatis.type.ByteArrayTypeHandler} AND tid = #{tid}

SELECT id, tuid, uid, session_id, tid, parent_tid, user_json, ai_json, created_at, last_accessed_at
FROM turns
WHERE session_id = #{sessionId,typeHandler=org.apache.ibatis.type.ByteArrayTypeHandler}
ORDER BY tid ASC
LIMIT #{offset}, #{limit}

